import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.CZxGLIO_.js";const b=JSON.parse('{"title":"备份、升级与恢复","description":"明确 GooseForum 备份范围，安全升级数据库与程序，并验证恢复结果。","frontmatter":{"title":"备份、升级与恢复","description":"明确 GooseForum 备份范围，安全升级数据库与程序，并验证恢复结果。"},"headers":[],"relativePath":"docs/gooseforum/maintenance/index.md","filePath":"docs/gooseforum/maintenance/index.md"}'),i={name:"docs/gooseforum/maintenance/index.md"};function r(d,e,l,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="备份、升级与恢复" tabindex="-1">备份、升级与恢复 <a class="header-anchor" href="#备份、升级与恢复" aria-label="Permalink to &quot;备份、升级与恢复&quot;">​</a></h1><p>一次有效备份必须能恢复站点数据和运行配置。只有程序压缩包，或只保存 SQLite 文件，都不能覆盖所有部署方式。</p><h2 id="需要备份哪些内容" tabindex="-1">需要备份哪些内容 <a class="header-anchor" href="#需要备份哪些内容" aria-label="Permalink to &quot;需要备份哪些内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>为什么需要</th></tr></thead><tbody><tr><td><code>config.toml</code></td><td>数据库连接、存储配置和系统密钥；MFA 等加密数据依赖原密钥</td></tr><tr><td>整个 <code>storage/</code></td><td>默认 SQLite、日志和本地备份等运行数据，实际范围取决于配置</td></tr><tr><td>外部 MySQL / PostgreSQL</td><td>不在本地 <code>storage/</code> 中，需使用对应数据库的备份工具</td></tr><tr><td>S3 对象及配置</td><td>本地数据库备份不会包含桶内文件</td></tr><tr><td>当前程序版本与提交</td><td>用于重建与数据匹配的运行环境</td></tr></tbody></table><p>将备份复制到独立存储，限制访问权限。备份中可能包含凭据、用户信息和私密附件。</p><h2 id="sqlite-自动备份" tabindex="-1">SQLite 自动备份 <a class="header-anchor" href="#sqlite-自动备份" aria-label="Permalink to &quot;SQLite 自动备份&quot;">​</a></h2><p>在已有 <code>[db]</code> 段检查：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backupSqlite = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backupDir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./storage/databasebackup/&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keep = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spec = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 3 * * *&quot;</span></span></code></pre></div><p>这表示启用 SQLite 定时备份、保留 7 份，计划时间为每日 03:00。确认运行环境时区、备份目录可写及磁盘空间，并观察实际产物和日志。它不会备份系统密钥、外部数据库或 S3 对象，同机备份也无法应对整机丢失。</p><p>手工复制 SQLite 时先停服再复制，避免只复制在线数据库主文件而遗漏 WAL 中的已提交数据。</p><h2 id="升级步骤" tabindex="-1">升级步骤 <a class="header-anchor" href="#升级步骤" aria-label="Permalink to &quot;升级步骤&quot;">​</a></h2><ol><li>阅读目标 <a href="https://github.com/leancodebox/GooseForum/releases" target="_blank" rel="noreferrer">Release</a>，记录当前版本、运行目录和数据库类型。</li><li>暂停写入并停止服务。使用前文 systemd 示例时执行 <code>sudo systemctl stop gooseforum</code>。</li><li>备份配置、数据库和存储，保留旧程序；外部数据库使用其一致性备份方式。</li><li>在临时目录解压并校验新发行包，只替换程序，保留原配置、密钥与数据目录。</li><li>检查 <code>[db].migration</code>。开启迁移时启动会执行升级所需结构变更；也可在同一运行目录使用 <code>./GooseForum migrate</code> 显式执行。</li><li>启动并检查日志，验证登录、分类、主题、回复、附件和后台设置。</li></ol><p>迁移失败时先保留错误信息，不要通过删除数据库或账号来让服务强行启动。历史用户名或邮箱规范化后冲突会导致唯一索引迁移失败，需要核对数据后解决。</p><h2 id="恢复与回退" tabindex="-1">恢复与回退 <a class="header-anchor" href="#恢复与回退" aria-label="Permalink to &quot;恢复与回退&quot;">​</a></h2><p>先在隔离目录或测试机器恢复，避免测试实例发送真实邮件或误写线上对象存储。停止目标服务，恢复相同备份时点的配置、数据库和所需文件，修正路径与权限后再启动匹配版本。</p><p>数据库迁移后，<strong>仅换回旧二进制不保证能够回退</strong>。应恢复升级前的数据库与相关文件，并使用保留的旧程序；恢复旧快照会丢失快照之后的新写入，需先明确恢复时点。</p><p>恢复验收至少包括：账号登录与 MFA、旧主题和图片可读、发布与回复、后台权限、邮件发送、备份再次生成。恢复演练通过后，记录耗时和所用版本。</p><h2 id="更新后浏览器仍显示旧内容" tabindex="-1">更新后浏览器仍显示旧内容 <a class="header-anchor" href="#更新后浏览器仍显示旧内容" aria-label="Permalink to &quot;更新后浏览器仍显示旧内容&quot;">​</a></h2><p>主站和后台通过 <code>/api/forum/status</code> 检测部署变化，并提示用户刷新，不强制丢弃未保存内容。前端嵌入二进制，源码构建必须先构建前端再构建 Go 程序。刷新仍失败时检查代理缓存、静态资源请求和实际运行的程序路径。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration_ZH.md" target="_blank" rel="noreferrer">备份配置</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">迁移命令</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">身份迁移</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/site-status.md" target="_blank" rel="noreferrer">更新提示</a>。</p>`,21)])])}const u=a(i,[["render",r]]);export{b as __pageData,u as default};
